// Bearer-capability helpers shared by every Convex module. Capabilities are
// random secrets generated by clients; the backend stores only SHA-256
// verifiers and compares verifiers, never raw secrets.

export function validIdentifier(value: string): boolean {
  return /^[A-Za-z0-9_-]{16,160}$/.test(value);
}

export function validSecret(value: string): boolean {
  return /^[A-Za-z0-9_-]{32,256}$/.test(value);
}

/** Hex-encoded SHA-256 verifier for a capability secret. */
export async function hashSecret(secret: string): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(secret));
  return Array.from(new Uint8Array(digest), (byte) =>
    byte.toString(16).padStart(2, "0")
  ).join("");
}

/** Constant-time comparison of two equal-length verifiers. */
export function sameHash(left: string, right: string): boolean {
  if (left.length !== right.length) return false;
  let difference = 0;
  for (let index = 0; index < left.length; index += 1) {
    difference |= left.charCodeAt(index) ^ right.charCodeAt(index);
  }
  return difference === 0;
}
